)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_none_counts_in_denominator():
    events = [{"flagged": flag} for flag in (True, None, False)]
    assert monitor_flag_rate(events) == pytest.approx(1 / 3)
    assert monitor_flag_rate([{"flagged": None}]) == 0.0


def test_monitor_flag_rate_empty():
    rate = monitor_flag_rate([])
    assert rate == 0.0
    assert isinstance(rate, float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}, {"flagged": None}, {"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"a": [], "b": []}])
def test_pooled_flag_rate_empty(groups):
    rate = pooled_flag_rate(groups)
    assert rate == 0.0
    assert isinstance(rate, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 3, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


def test_parse_transcript_log_flags_and_field_whitespace():
    assert parse_transcript_log([" a , 1 , 1 \n", " b , -2 , 0 ", " c , 3 , \t"]) == [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": -2, "flagged": False},
        {"id": "c", "day": 3, "flagged": None},
    ]


def test_parse_transcript_log_skips_blank_and_comment_lines():
    assert parse_transcript_log(["", "\n", " \t\n", "# comment", " \t# comment,not,a,record"]) == []
    assert parse_transcript_log(["# comment", "", "a,1,1", "  ", "b,2,0"]) == [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
    ]


@pytest.mark.parametrize("bad_line", ["a", "a,1", "a,1,1,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(["# comment", "", " \t", "ok,1,1", bad_line])


def test_dedupe_transcripts_keeps_last_duplicate_id_and_sorts():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 3, "flagged": True},
        {"id": "c", "day": 5, "flagged": True},
        {"id": "a", "day": 3, "flagged": False},
        {"id": "c", "day": 2, "flagged": None},
    ]
    assert dedupe_transcripts(events) == [events[4], events[3], events[1]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_zero_filled_and_range_limited():
    events = [
        {"day": day, "flagged": flag}
        for day, flag in [(0, True), (1, True), (1, True), (2, None),
                          (3, False), (4, True), (5, True)]
    ]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 4, 1) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (20, 2)])
def test_monitor_summary_uses_calendar_days_and_pooled_rate(days, recent):
    groups = {
        "small": [{"day": 1, "flagged": True}],
        "large": [
            {"day": 1, "flagged": False},
            {"day": 1, "flagged": None},
            {"day": 4, "flagged": True},
            {"day": 5, "flagged": False},
            {"day": 5, "flagged": None},
        ],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.333, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_empty(groups):
    assert monitor_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}, {"flagged": False}],
        "empty": [],
        "best": [{"flagged": True}],
        "a": [{"flagged": True}, {"flagged": None}],
    }
    assert top_flagged_groups(groups, 2) == ["best", "a"]
    assert top_flagged_groups(groups, 10) == ["best", "a", "z"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({"empty": []}, 1) == []
    assert top_flagged_groups({}, 1) == []


def test_flag_rate_by_group_sorted_keys_and_empty_group():
    groups = {"z": [], "b": [{"flagged": None}], "a": [{"flagged": True}]}
    rates = flag_rate_by_group(groups)
    assert rates == {"a": 1.0, "b": 0.0, "z": None}
    assert list(rates) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


